namespace sv_dbb3bede6df6430181733b31f438e6b8.Services;

public class WarehouseInfo(string id, string name)
{
    public string Id { get; } = id;
    public string Name { get; } = name;
}

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single circuit.
/// Each user's browser tab gets its own instance, so selections are independent.
/// </summary>
public class WarehouseStateService
{
    public static IReadOnlyList<WarehouseInfo> AvailableWarehouses { get; } =
    [
        new("wh-a", "Warehouse A"),
        new("wh-b", "Warehouse B"),
        new("wh-c", "Warehouse C"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name
        ?? _currentWarehouseId;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_dbb3bede6df6430181733b31f438e6b8.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts on the current warehouse.
/// Polling is reference-counted: multiple components can request polling and it
/// runs as long as at least one subscriber is active.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Fired on the polling thread whenever new alert data arrives.
    /// Subscribers must marshal to the UI thread with InvokeAsync.
    /// </summary>
    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
    }

    /// <summary>Simulates a database query — returns a random number 0-15.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Starts polling if not already running. Safe to call multiple times;
    /// uses reference counting so polling stops only when all subscribers unsubscribe.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _cts?.Cancel();
            _timer?.Dispose();
            _timer = null;
            _cts?.Dispose();
            _cts = null;
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fire immediately on start, then every 10 seconds.
        await FetchAndNotifyAsync();

        while (_timer is not null)
        {
            try
            {
                if (!await _timer.WaitForNextTickAsync(ct))
                    break;
            }
            catch (OperationCanceledException)
            {
                break;
            }

            await FetchAndNotifyAsync();
        }
    }

    private async Task FetchAndNotifyAsync()
    {
        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnAlertCountChanged?.Invoke();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

