namespace sv_dbb3bede6df6430181733b31f438e6b8.Services;

public class WarehouseInfo(string id, string name)
{
    public string Id { get; } = id;
    public string Name { get; } = name;
}

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single circuit.
/// Each user's browser tab gets its own instance, so selections are independent.
/// </summary>
public class WarehouseStateService
{
    public static IReadOnlyList<WarehouseInfo> AvailableWarehouses { get; } =
    [
        new("wh-a", "Warehouse A"),
        new("wh-b", "Warehouse B"),
        new("wh-c", "Warehouse C"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name
        ?? _currentWarehouseId;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

