@using sv_dbb3bede6df6430181733b31f438e6b8.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouse-select" class="form-label mb-0 me-2 text-nowrap">Warehouse:</label>
    <select id="warehouse-select"
            class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
        }
    }

    // Re-render if another component changes the warehouse programmatically
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

.warehouse-selector {
    display: flex;
    align-items: center;
}

.warehouse-selector .form-select {
    width: auto;
    min-width: 160px;
}

@using sv_dbb3bede6df6430181733b31f438e6b8.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<span class="alert-badge-wrapper">
    ⚠️ Low Stock
    @if (AlertService.CurrentLowStockCount > 0)
    {
        <span class="badge bg-danger rounded-pill ms-1">@AlertService.CurrentLowStockCount</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill ms-1">0</span>
    }
</span>

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += OnCountChanged;
    }

    private void OnCountChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= OnCountChanged;
    }
}

@page "/dashboard"
@using sv_dbb3bede6df6430181733b31f438e6b8.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard - @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">@WarehouseState.CurrentWarehouseName</p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            Items below minimum levels:
            <span class="badge @(AlertService.CurrentLowStockCount > 0 ? "bg-danger" : "bg-success") fs-5">
                @AlertService.CurrentLowStockCount
            </span>
        </p>
        <p class="text-muted"><small>Refreshes automatically every 10 seconds.</small></p>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertChanged;
        AlertService.StartPolling();
    }

    private void OnWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void OnAlertChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.StopPolling();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertChanged;
    }
}

